import { z } from "zod";
import { createForm, zodResolver } from "qortex-form";

const schema = z.object({
  name: z.string().min(1),
  email: z.string().email(),
});

const form = createForm({
  initialData: { name: "", email: "" },
  validate: {
    resolver: zodResolver(schema),
    on: "submit",
  },
});
